import { describe, it, expect } from 'vitest';
import {
  CricketDataOrgProvider,
  MatchSchema,
  getTeamCode,
  QuotaGuard,
} from '../src/index.js';

describe('CricketDataOrgProvider Tests', () => {
  const provider = new CricketDataOrgProvider({ apiKey: '', useOfflineFixturesOnly: true });

  it('normalizes real currentMatches response into valid LiveCricket Match models', async () => {
    const matches = await provider.getCurrentMatches();
    expect(matches.length).toBe(25);

    for (const match of matches) {
      const parsed = MatchSchema.safeParse(match);
      if (!parsed.success) {
        console.error(`Validation error for match ${match.id}:`, parsed.error);
      }
      expect(parsed.success).toBe(true);
    }
  });

  it('correctly categorizes real LIVE and FINISHED matches from fixture', async () => {
    const matches = await provider.getCurrentMatches();

    const liveMatches = matches.filter((m) => m.status === 'live');
    const finishedMatches = matches.filter((m) => m.status === 'completed' || m.status === 'abandoned');

    expect(liveMatches.length).toBe(1);
    expect(finishedMatches.length).toBe(24);

    // Verify real live match (Adelaide Strikers Women vs Hobart Hurricanes Women)
    const liveMatch = liveMatches[0];
    expect(liveMatch).toBeDefined();
    expect(liveMatch.id).toBe('f3064046-a1c8-458f-996e-0dbaa34531e7');
    expect(liveMatch.teamA.code).toBe('ADS');
    expect(liveMatch.teamB.code).toBe('HBH');
    expect(liveMatch.status).toBe('live');
    expect(liveMatch.format).toBe('T20');
    expect(liveMatch.matchNumber).toBe('9th Match');
    expect(liveMatch.teamAScore?.runs).toBe(165);
    expect(liveMatch.teamBScore?.runs).toBe(31);
    expect(liveMatch.statusText).toContain('Hobart Hurricanes Women need');

    // Verify rain-abandoned match (Sydney Thunder Women vs Brisbane Heat Women)
    const abandonedMatch = matches.find((m) => m.id === '57e4d85e-0474-4b34-b30d-b0b24f937040');
    expect(abandonedMatch?.status).toBe('abandoned');
    expect(abandonedMatch?.teamA.code).toBe('SYT');
    expect(abandonedMatch?.teamB.code).toBe('BRH');

    // Verify comma-split team parsing (Hong Kong, China vs Singapore)
    const hkSinMatch = matches.find((m) => m.id === '4a378ea0-b156-47f1-8127-c2bfb65f765d');
    expect(hkSinMatch).toBeDefined();
    expect(hkSinMatch?.teamA.code).toBe('HK');
    expect(hkSinMatch?.teamB.code).toBe('SIN');
    expect(hkSinMatch?.teamAScore?.display).toBe('172/5 (20)');
    expect(hkSinMatch?.teamBScore?.display).toBe('134 (18)');
  });

  it('robustly maps national, franchise, and domestic team names to 3-letter codes', () => {
    expect(getTeamCode('India')).toBe('IND');
    expect(getTeamCode('Pakistan')).toBe('PAK');
    expect(getTeamCode('Australia Women')).toBe('AUS');
    expect(getTeamCode('Bangladesh Women')).toBe('BAN');
    expect(getTeamCode('Thailand')).toBe('THA');
    expect(getTeamCode('Bahrain')).toBe('BHR');
    expect(getTeamCode('Qatar')).toBe('QAT');
    expect(getTeamCode('Myanmar')).toBe('MYA');
    expect(getTeamCode('Mongolia')).toBe('MGL');
    expect(getTeamCode('Bhutan')).toBe('BHU');
    expect(getTeamCode('Kuwait')).toBe('KUW');
    expect(getTeamCode('Maldives')).toBe('MDV');
    expect(getTeamCode('Saudi Arabia')).toBe('KSA');
    expect(getTeamCode('China')).toBe('CHN');
    expect(getTeamCode('Hong Kong, China')).toBe('HK');
    expect(getTeamCode('Singapore')).toBe('SIN');
    expect(getTeamCode('Adelaide Strikers Women')).toBe('ADS');
    expect(getTeamCode('Hobart Hurricanes Women')).toBe('HBH');
    expect(getTeamCode('Chennai Super Kings')).toBe('CSK');
    expect(getTeamCode('Mumbai Indians')).toBe('MI');
    expect(getTeamCode('Western Australia')).toBe('WA');
  });

  it('enforces quota budget and safety margin', () => {
    const dailyBudget = 100;
    const safetyMargin = 0.8;
    const usableBudget = Math.floor(dailyBudget * safetyMargin); // 80 calls

    const guard = new QuotaGuard({
      providerName: 'CricketDataOrg',
      dailyBudget: usableBudget,
      maxCallsPerMinute: 200,
    });

    for (let i = 0; i < usableBudget; i++) {
      expect(() => guard.checkQuota()).not.toThrow();
      guard.recordCall();
    }

    const stats = guard.getStats();
    expect(stats.callsToday).toBe(80);
    expect(stats.remainingCallsToday).toBe(0);

    // Call #81 must be blocked
    expect(() => guard.checkQuota()).toThrow(/Daily API quota budget of 80 calls exceeded/);
  });
});
